@@ -0,0 +1,117 @@
+using System.Net;
+using Uinsure.Policies.Api.Tests.Builders;
+using Uinsure.Policies.Api.Tests.Support;
+using Xunit;
+
+namespace Uinsure.Policies.Api.Tests;
+
+// GET-1 status: derived from UK today on each request, never stored. Pending before the first start, Active
+// from the start to the end inclusive, Expired after the end (Cancelled is F3's). Each side of each boundary
+// is its own test: the policy is sold on TestClock.Today, then the clock moves to the day under test and the
+// policy is read back whole. A policy sold to start 2026-11-08 ends on 2027-11-07; one sold to start today
+// (2026-10-17) ends on 2027-10-16, which is in BST, so 23:30 UTC that day is already 17 October in the UK.
+public sealed class RetrieveStatusTests : IClassFixture<PoliciesApiFactory>
+{
+    private static readonly DateOnly FutureStart = new(2026, 11, 8);
+    private static readonly DateOnly FutureStartEnd = new(2027, 11, 7);
+    private static readonly DateOnly TodayStartEnd = new(2027, 10, 16);
+
+    private readonly PoliciesApiFactory _factory;
+
+    public RetrieveStatusTests(PoliciesApiFactory factory)
+    {
+        _factory = factory;
+        _factory.ResetClock();
+    }
+
+    [Fact]
+    [Trait("Rule", "GET-1")]
+    public async Task Policy_sold_to_start_in_the_future_reads_back_Pending()
+    {
+        using var client = _factory.CreateClient();
+        var sold = new SellPolicyRequestBuilder("GET1-PENDING").WithStartDate(FutureStart).Build();
+
+        var policy = await client.SellAndReadBack(sold, "GET1-PENDING");
+
+        PolicyResponseAssert.ReadsBackAsSold(policy, sold, "GET1-PENDING", FutureStartEnd, "Pending");
+    }
+
+    [Fact]
+    [Trait("Rule", "GET-1")]
+    public async Task Policy_sold_to_start_today_reads_back_Active()
+    {
+        using var client = _factory.CreateClient();
+        var sold = new SellPolicyRequestBuilder("GET1-ACTIVE-TODAY").WithStartDate(TestClock.Today).Build();
+
+        var policy = await client.SellAndReadBack(sold, "GET1-ACTIVE-TODAY");
+
+        PolicyResponseAssert.ReadsBackAsSold(policy, sold, "GET1-ACTIVE-TODAY", TodayStartEnd, "Active");
+    }
+
+    [Fact]
+    [Trait("Rule", "GET-1")]
+    public async Task Status_on_the_day_before_the_start_is_Pending()
+    {
+        await AssertStatusOn("GET1-START-MINUS-1", FutureStart, FutureStartEnd, new DateTimeOffset(2026, 11, 7, 12, 0, 0, TimeSpan.Zero), "Pending");
+    }
+
+    [Fact]
+    [Trait("Rule", "GET-1")]
+    public async Task Status_on_the_start_date_is_Active()
+    {
+        await AssertStatusOn("GET1-START-DAY", FutureStart, FutureStartEnd, new DateTimeOffset(2026, 11, 8, 12, 0, 0, TimeSpan.Zero), "Active");
+    }
+
+    [Fact]
+    [Trait("Rule", "GET-1")]
+    public async Task Status_on_the_end_date_is_Active()
+    {
+        await AssertStatusOn("GET1-END-DAY", FutureStart, FutureStartEnd, new DateTimeOffset(2027, 11, 7, 12, 0, 0, TimeSpan.Zero), "Active");
+    }
+
+    [Fact]
+    [Trait("Rule", "GET-1")]
+    public async Task Status_on_the_day_after_the_end_date_is_Expired()
+    {
+        await AssertStatusOn("GET1-END-PLUS-1", FutureStart, FutureStartEnd, new DateTimeOffset(2027, 11, 8, 12, 0, 0, TimeSpan.Zero), "Expired");
+    }
+
+    // GMT control: 2027-11-07 is after the clocks go back, so 23:30 UTC is still 7 November in the UK.
+    [Fact]
+    [Trait("Rule", "GET-1")]
+    public async Task Status_at_23_30_UTC_on_an_end_date_in_GMT_is_Active()
+    {
+        await AssertStatusOn("GET1-END-GMT", FutureStart, FutureStartEnd, new DateTimeOffset(2027, 11, 7, 23, 30, 0, TimeSpan.Zero), "Active");
+    }
+
+    // BST: at 23:30 UTC on 2027-10-16 the UK date is already 2027-10-17, the day after the end.
+    [Fact]
+    [Trait("Rule", "GET-1")]
+    public async Task Status_at_23_30_UTC_on_an_end_date_in_BST_is_Expired_as_the_UK_date_is_the_next_day()
+    {
+        await AssertStatusOn("GET1-END-BST", TestClock.Today, TodayStartEnd, new DateTimeOffset(2027, 10, 16, 23, 30, 0, TimeSpan.Zero), "Expired");
+    }
+
+    // BST control: at 22:59 UTC on 2027-10-16 it is 23:59 in the UK, still the end date.
+    [Fact]
+    [Trait("Rule", "GET-1")]
+    public async Task Status_at_22_59_UTC_on_an_end_date_in_BST_is_Active()
+    {
+        await AssertStatusOn("GET1-END-BST-CTRL", TestClock.Today, TodayStartEnd, new DateTimeOffset(2027, 10, 16, 22, 59, 0, TimeSpan.Zero), "Active");
+    }
+
+    // Sold on TestClock.Today, read back whole at the instant under test: the one term is the current term
+    // whatever the status, because a policy outside every term shows its latest.
+    private async Task AssertStatusOn(string reference, DateOnly start, DateOnly expectedEnd, DateTimeOffset readAt, string expectedStatus)
+    {
+        using var client = _factory.CreateClient();
+        var sold = new SellPolicyRequestBuilder(reference).WithStartDate(start).Build();
+        await client.SellAndReadBack(sold, reference);
+
+        _factory.Clock.SetUtcNow(readAt);
+        using var read = await client.GetPolicy(reference);
+
+        Assert.Equal(HttpStatusCode.OK, read.StatusCode);
+        PolicyResponseAssert.ReadsBackAsSold(await read.ReadJson(), sold, reference, expectedEnd, expectedStatus);
+    }
+}
diff --git a/tests/Uinsure.Policies.Api.Tests/Support/PolicyResponseAssert.cs b/tests/Uinsure.Policies.Api.Tests/Support/PolicyResponseAssert.cs
new file mode 100644
index 00000000..2ef24e57
--- /dev/null
+++ b/tests/Uinsure.Policies.Api.Tests/Support/PolicyResponseAssert.cs
@@ -0,0 +1,85 @@
+using System.Text.Json;
+using System.Text.Json.Nodes;
+using Xunit;
+
+namespace Uinsure.Policies.Api.Tests.Support;
+
+// The full PolicyResponse of the API contract (GET-1), read back. It extends the F1 read-back
+// (SoldPolicyAssert) with the members F2 adds: status, currentTermNumber, hasClaims, refunds, claims and
+// cancellation, and it pins the member set of every object, so a field missing, renamed or extra fails.
+// Status and the end date are the test's own literals, never derived here.
+internal static class PolicyResponseAssert
+{
+    private static readonly string[] PolicyMembers =
+    [
+        "reference", "type", "status", "currentTermNumber", "startDate", "endDate", "amount", "hasClaims",
+        "autoRenew", "policyholders", "property", "terms", "payments", "refunds", "claims", "cancellation",
+    ];
+
+    private static readonly string[] PolicyholderMembers = ["firstName", "lastName", "dateOfBirth"];
+    private static readonly string[] PropertyMembers = ["addressLine1", "addressLine2", "addressLine3", "postcode"];
+    private static readonly string[] TermMembers = ["termNumber", "startDate", "endDate", "amount", "paymentReference"];
+    private static readonly string[] PaymentMembers = ["reference", "type", "amount"];
+
+    // A sold, one-term policy read back whole: every value sold, its term and payment, the derived status,
+    // term 1 as the current term, no claims, no refunds and no cancellation.
+    public static void ReadsBackAsSold(JsonElement policy, JsonObject sold, string expectedReference, DateOnly expectedEndDate, string expectedStatus)
+    {
+        HasTheContractShape(policy);
+        SoldPolicyAssert.ReadsBackAsSold(policy, sold, expectedReference, expectedEndDate);
+        Assert.Equal(expectedStatus, policy.Member("status").GetString());
+        Assert.Equal(1, policy.Member("currentTermNumber").GetInt32());
+        HasNoClaimsRefundsOrCancellation(policy);
+    }
+
+    // The policy-level view of the current term (GET-1): its number, dates and amount.
+    public static void ShowsCurrentTerm(JsonElement policy, int termNumber, DateOnly start, DateOnly end, decimal amount)
+    {
+        Assert.Equal(termNumber, policy.Member("currentTermNumber").GetInt32());
+        Assert.Equal(start, policy.GetDate("startDate"));
+        Assert.Equal(end, policy.GetDate("endDate"));
+        Assert.Equal(amount, policy.Member("amount").GetDecimal());
+    }
+
+    // A sold policy has no claim (hasClaims false at sale), no refund and no cancellation.
+    public static void HasNoClaimsRefundsOrCancellation(JsonElement policy)
+    {
+        Assert.False(policy.Member("hasClaims").GetBoolean());
+        Assert.Equal(JsonValueKind.Array, policy.Member("refunds").ValueKind);
+        Assert.Empty(policy.Member("refunds").EnumerateArray());
+        Assert.Equal(JsonValueKind.Array, policy.Member("claims").ValueKind);
+        Assert.Empty(policy.Member("claims").EnumerateArray());
+        Assert.Equal(JsonValueKind.Null, policy.Member("cancellation").ValueKind);
+    }
+
+    // Exactly the contract's members on the policy, each policyholder, the property, each term and each
+    // payment. Refund, claim and cancellation members are F3's, asserted where those exist.
+    public static void HasTheContractShape(JsonElement policy)
+    {
+        HasMembers(policy, PolicyMembers, "policy");
+        HasMembers(policy.Member("property"), PropertyMembers, "property");
+        foreach (var holder in policy.Member("policyholders").EnumerateArray())
+        {
+            HasMembers(holder, PolicyholderMembers, "policyholder");
+        }
+
+        foreach (var term in policy.Member("terms").EnumerateArray())
+        {
+            HasMembers(term, TermMembers, "term");
+        }
+
+        foreach (var payment in policy.Member("payments").EnumerateArray())
+        {
+            HasMembers(payment, PaymentMembers, "payment");
+        }
+    }
+
+    private static void HasMembers(JsonElement element, string[] expected, string what)
+    {
+        Assert.Equal(JsonValueKind.Object, element.ValueKind);
+        var actual = element.EnumerateObject().Select(member => member.Name).Order(StringComparer.Ordinal).ToArray();
+        Assert.True(
+            expected.Order(StringComparer.Ordinal).SequenceEqual(actual),
+            $"The {what} members are [{string.Join(", ", actual)}]; the contract has [{string.Join(", ", expected)}].");
+    }
+}
